import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function ProfilePage() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token");
      if (!token) {
        navigate("/login");
        return;
      }
      try {
        const response = await fetch("http://localhost:5000/api/auth/profile", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await response.json();
        if (!response.ok) {
          setError(data.message);
        } else {
          setUser(data);
        }
      } catch (err) {
        setError("Something went wrong.");
      }
      setLoading(false);
    };
    fetchProfile();
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/login");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p className="text-gray-500 text-lg">Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p className="text-red-500 text-lg">{error}</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-md">
        <h2 className="text-2xl font-bold text-center text-blue-600 mb-6">
          My Profile
        </h2>
        <div className="flex items-center justify-center mb-6">
          <div className="bg-blue-600 text-white rounded-full w-20 h-20 flex items-center justify-center text-3xl font-bold">
            {user?.name?.charAt(0).toUpperCase()}
          </div>
        </div>
        <div className="mb-4">
          <label className="block text-gray-500 text-sm mb-1">Full Name</label>
          <p className="text-gray-800 font-semibold text-lg">{user?.name}</p>
        </div>
        <div className="mb-4">
          <label className="block text-gray-500 text-sm mb-1">Email</label>
          <p className="text-gray-800 font-semibold">{user?.email}</p>
        </div>
        <div className="mb-6">
          <label className="block text-gray-500 text-sm mb-1">Role</label>
          <span className={`px-3 py-1 rounded-full text-sm font-semibold ${
            user?.role === "recruiter"
              ? "bg-green-100 text-green-700"
              : "bg-blue-100 text-blue-700"
          }`}>
            {user?.role === "recruiter" ? "Recruiter" : "Student"}
          </span>
        </div>
        <button
          onClick={handleLogout}
          className="w-full bg-red-500 text-white py-2 rounded font-semibold hover:bg-red-600 transition"
        >
          Logout
        </button>
      </div>
    </div>
  );
}

export default ProfilePage;
